#!/bin/bash
# Mirror the knowledge base in docs/ (a nested git repo) into THIS repo's index as plain files.
#
# `git add docs/` would record only a gitlink (a pointer to the nested repo) and push no content, so the files are staged
# with plumbing (hash-object + update-index) instead. The nested repo and its .git are never touched.
# Left out on purpose: docs/.git, docs/kb/.lock, and docs/scripts/ (the vendored Corvin KB engine: no licence header,
# regenerated by the Knowledge Graph plugin, not part of the research content).
# Afterwards review with `git status` / `git diff --cached --stat` and commit as usual.
set -euo pipefail
cd "$(dirname "$0")/.."
[ -d docs/.git ] || { echo "docs/ is not a nested repo; use plain 'git add docs'"; exit 1; }
n=0
while IFS= read -r -d '' f; do
  sha=$(git hash-object -w -- "$f")
  mode=100644; [ -x "$f" ] && mode=100755
  git update-index --add --cacheinfo "$mode,$sha,$f"
  n=$((n + 1))
done < <(find docs -type f -not -path 'docs/.git/*' -not -path 'docs/scripts/*' -not -path 'docs/kb/.lock' \
              -not -path '*/__pycache__/*' -not -path 'docs/data/scratch/*' -print0)
echo "staged $n files from docs/"
